    # Wythoff's game: losing positions are (floor(k*phi), floor(k*phi^2))
    lose = set()
    k = 0
    while True:
        x = int(k * 1.6180339887498948482)
        y = x + k
        if x > 25 and y > 25:
            break
        lose.add((x, y))
        lose.add((y, x))
        k += 1
    if (a, b) in lose:
        print("LOSE")
