    best = None
    for i in range(0, a + 1):
        for j in range(0, b + 1):
            if i == 0 and j == 0:
                continue
            if (i == 0 or j == 0 or i == j) and (a - i, b - j) in lose:
                if best is None or (i, j) < best:
                    best = (i, j)
    i, j = best
    print(f"WIN {i} {j}")

